script:
/* =========================================================
   RELATED PRODUCTS SECTION
   ========================================================= */

.related-products-section {
    width: 100% !important;

    background: #eef3f1 !important;

    padding: 50px 4% 60px !important;

    margin: 0 !important;

    box-sizing: border-box !important;

    overflow: hidden !important;
}

.related-products-section *,
.related-products-section *::before,
.related-products-section *::after {
    box-sizing: border-box !important;
}


/* =========================================================
   SECTION HEADING
   ========================================================= */

.related-products-section .related-heading {
    width: 100% !important;

    margin: 0 0 30px 0 !important;
    padding: 0 !important;

    color: #111111 !important;

    font-size: 48px !important;
    line-height: 1.1 !important;
    font-weight: 400 !important;

    text-align: center !important;
}


/* =========================================================
   OUTER WRAPPER
   ========================================================= */

.related-products-section > .related-product {
    width: 100% !important;

    /*
       Smaller overall width so the cards
       don't stretch across the whole page
    */
    max-width: 1250px !important;

    height: auto !important;

    min-height: 0 !important;
    max-height: none !important;

    margin: 0 auto !important;
    padding: 0 !important;

    background: transparent !important;

    border: none !important;
    border-radius: 0 !important;

    box-shadow: none !important;

    display: block !important;

    overflow: visible !important;
}


/* =========================================================
   PRODUCT GRID
   ========================================================= */

.related-products-section .related-product-grid {
    width: 100% !important;

    display: grid !important;

    grid-template-columns:
        repeat(2, minmax(0, 1fr)) !important;

    /*
       Comfortable space between cards
    */
    gap: 30px !important;

    margin: 0 !important;
    padding: 0 !important;

    align-items: stretch !important;

    background: transparent !important;

    border: none !important;
    border-radius: 0 !important;

    box-shadow: none !important;
}


/* =========================================================
   PRODUCT CARD
   ========================================================= */

.related-products-section .related-product-card {
    width: 100% !important;

    min-width: 0 !important;
    max-width: 100% !important;

    /*
       Smaller card height
    */
    min-height: 430px !important;

    margin: 0 !important;

    padding: 0 0 24px 0 !important;

    background: #ffffff !important;

    border: 1px solid #d6dedb !important;

    /*
       More card-like rounded corners
    */
    border-radius: 12px !important;

    overflow: hidden !important;

    display: flex !important;

    flex-direction: column !important;

    position: relative !important;

    /*
       Very subtle shadow
    */
    box-shadow:
        0 3px 12px rgba(16, 38, 54, 0.06) !important;

    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease !important;
}


/* =========================================================
   CARD HOVER
   ========================================================= */

.related-products-section .related-product-card:hover {
    transform: translateY(-3px) !important;

    box-shadow:
        0 10px 24px rgba(16, 38, 54, 0.10) !important;
}


/* =========================================================
   PRODUCT IMAGE
   IMPORTANT:
   .product_image IS THE ACTUAL IMG ELEMENT
   ========================================================= */

.related-products-section img.product_image {
    order: 1 !important;

    display: block !important;

    width: 100% !important;

    /*
       Smaller image area
    */
    height: 220px !important;

    min-width: 0 !important;
    min-height: 220px !important;

    max-width: 100% !important;
    max-height: 220px !important;

    flex: 0 0 220px !important;

    margin: 0 !important;

    /*
       Smaller side padding
    */
    padding: 15px 28px !important;

    background: #ffffff !important;

    border: none !important;
    border-radius: 0 !important;

    /*
       IMPORTANT:
       Keep complete product visible
    */
    object-fit: contain !important;

    object-position: center center !important;

    overflow: hidden !important;
}


/* =========================================================
   IF IMAGE HAS AN INNER IMG
   ========================================================= */

.related-products-section .product_image img {
    width: auto !important;

    height: auto !important;

    max-width: 100% !important;

    max-height: 100% !important;

    margin: 0 !important;

    padding: 0 !important;

    object-fit: contain !important;

    object-position: center center !important;

    display: block !important;
}


/* =========================================================
   CATEGORY / EYEBROW
   ========================================================= */

.related-products-section .related-eyebrow {
    order: 2 !important;

    width: 100% !important;

    margin: 0 !important;

    /*
       Slightly tighter than before
    */
    padding: 16px 26px 0 !important;

    flex: 0 0 auto !important;
}


.related-products-section .related-eyebrow-text {
    display: block !important;

    margin: 0 !important;

    padding: 0 !important;

    color: #164b7a !important;

    font-size: 11px !important;

    line-height: 1.3 !important;

    font-weight: 700 !important;

    letter-spacing: 1.2px !important;

    text-transform: uppercase !important;
}


/* =========================================================
   DESCRIPTION
   ========================================================= */

.related-products-section .related-description {
    order: 3 !important;

    width: auto !important;

    margin: 10px 26px 0 !important;

    padding: 0 !important;

    color: #667983 !important;

    font-size: 15px !important;

    line-height: 1.5 !important;

    font-weight: 400 !important;

    white-space: normal !important;

    overflow: hidden !important;

    display: -webkit-box !important;

    -webkit-box-orient: vertical !important;

    -webkit-line-clamp: 3 !important;

    flex: 0 0 auto !important;
}


/* =========================================================
   VIEW PRODUCT LINK
   ========================================================= */

.related-products-section .related-product-link {
    display: inline-flex !important;

    align-items: center !important;

    gap: 7px !important;

    width: fit-content !important;

    margin: auto 26px 0 !important;

    padding: 0 !important;

    color: #ff6b16 !important;

    background: transparent !important;

    border: none !important;

    font-size: 14px !important;

    line-height: 1.4 !important;

    font-weight: 600 !important;

    text-decoration: none !important;

    cursor: pointer !important;
}


.related-products-section .related-product-link::after {
    content: "→" !important;

    font-size: 17px !important;

    transition: transform 0.2s ease !important;
}


.related-products-section .related-product-link:hover {
    color: #e85b0b !important;
}


.related-products-section .related-product-link:hover::after {
    transform: translateX(4px) !important;
}


/* =========================================================
   REMOVE DEFAULT SPACING
   ========================================================= */

.related-products-section .related-product-card p,
.related-products-section .related-product-card h1,
.related-products-section .related-product-card h2,
.related-products-section .related-product-card h3 {
    box-sizing: border-box !important;
}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 900px) {

    .related-products-section {
        padding: 42px 4% 55px !important;
    }


    .related-products-section .related-heading {
        font-size: 40px !important;

        margin-bottom: 25px !important;
    }


    .related-products-section > .related-product {
        max-width: 760px !important;
    }


    .related-products-section .related-product-grid {
        gap: 20px !important;
    }


    .related-products-section .related-product-card {
        min-height: 400px !important;
    }


    .related-products-section img.product_image {
        height: 200px !important;

        min-height: 200px !important;

        max-height: 200px !important;

        flex-basis: 200px !important;

        padding: 15px 22px !important;
    }


    .related-products-section .related-eyebrow {
        padding: 15px 22px 0 !important;
    }


    .related-products-section .related-description {
        margin-left: 22px !important;
        margin-right: 22px !important;
    }


    .related-products-section .related-product-link {
        margin-left: 22px !important;
        margin-right: 22px !important;
    }
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 650px) {

    .related-products-section {
        padding: 38px 20px 50px !important;
    }


    .related-products-section .related-heading {
        font-size: 34px !important;

        margin-bottom: 22px !important;
    }


    .related-products-section > .related-product {
        max-width: 100% !important;
    }


    .related-products-section .related-product-grid {
        grid-template-columns: 1fr !important;

        gap: 18px !important;
    }


    .related-products-section .related-product-card {
        min-height: 0 !important;

        padding-bottom: 24px !important;
    }


    .related-products-section img.product_image {
        height: 210px !important;

        min-height: 210px !important;

        max-height: 210px !important;

        flex-basis: 210px !important;

        padding: 15px 25px !important;
    }


    .related-products-section .related-eyebrow {
        padding: 14px 22px 0 !important;
    }


    .related-products-section .related-description {
        margin: 9px 22px 0 !important;

        font-size: 14px !important;
    }


    .related-products-section .related-product-link {
        margin-left: 22px !important;

        margin-right: 22px !important;
    }
}

/* =========================================================
   RELATED PRODUCTS — COMPLETE FINAL CSS
   ========================================================= */


/* =========================================================
   MAIN RELATED PRODUCTS SECTION
   ========================================================= */

#related-products {
    width: 1100px !important;
    max-width: calc(100% - 80px) !important;

    margin: 55px auto 40px auto !important;

    padding: 30px !important;

    box-sizing: border-box !important;

    background: #eef1ef !important;

    border: 1px solid #dfe4e1 !important;
    border-radius: 8px !important;

    display: grid !important;

    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;

    gap: 24px !important;

    align-items: stretch !important;

    overflow: visible !important;
}


/* =========================================================
   RELATED PRODUCTS HEADING
   ========================================================= */

.related-heading {
    grid-column: 1 / -1 !important;

    margin: 0 !important;
    padding: 0 !important;

    color: #071b2b !important;

    font-size: 18px !important;
    line-height: 1.2 !important;

    font-weight: 600 !important;
}


/* =========================================================
   RELATED PRODUCT CARD
   ========================================================= */

.related-product {
    width: 100% !important;
    max-width: none !important;

    margin: 0 !important;
    padding: 24px !important;

    box-sizing: border-box !important;

    background: #ffffff !important;

    border: 1px solid #dfe4e1 !important;
    border-radius: 8px !important;

    display: grid !important;

    grid-template-columns: 1fr 1fr !important;

    grid-template-rows: auto 1fr !important;

    column-gap: 20px !important;
    row-gap: 14px !important;

    align-items: start !important;

    overflow: hidden !important;

    transition:
        transform 0.3s ease,
        border-color 0.3s ease,
        box-shadow 0.3s ease !important;
}


/* =========================================================
   ORANGE HOVER
   ========================================================= */

.related-product:hover {
    transform: translateY(-5px) !important;

    border-color: #f28c28 !important;

    box-shadow:
        0 10px 24px rgba(242, 140, 40, 0.18) !important;
}


/* =========================================================
   CATEGORY / EYEBROW
   ========================================================= */

.related-eyebrow {
    grid-column: 1 !important;
    grid-row: 1 !important;

    width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    color: #71859a !important;

    font-size: 9px !important;
    line-height: 1.3 !important;

    font-weight: 600 !important;

    letter-spacing: 1.3px !important;

    text-transform: uppercase !important;

    transition: color 0.25s ease !important;
}


.related-product:hover .related-eyebrow {
    color: #f28c28 !important;
}


/* =========================================================
   TITLE
   ========================================================= */

.related-title {
    grid-column: 2 !important;
    grid-row: 1 !important;

    width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    color: #071b2b !important;

    font-size: 30px !important;
    line-height: 1.1 !important;

    font-weight: 700 !important;

    letter-spacing: -0.5px !important;

    text-align: left !important;

    transition: color 0.25s ease !important;
}


.related-product:hover .related-title {
    color: #f28c28 !important;
}


/* =========================================================
   IMAGE
   ========================================================= */

.related-image {
    grid-column: 1 !important;
    grid-row: 2 !important;

    display: block !important;

    width: 100% !important;
    height: 190px !important;

    margin: 0 !important;
    padding: 10px !important;

    box-sizing: border-box !important;

    background: #f8faf9 !important;

    border: 1px solid #d8ddda !important;
    border-radius: 6px !important;

    object-fit: contain !important;
    object-position: center !important;

    transition:
        transform 0.3s ease,
        border-color 0.3s ease,
        background 0.3s ease !important;
}


.related-product:hover .related-image {
    transform: scale(1.02) !important;

    border-color: #f28c28 !important;

    background: #fff8f0 !important;
}


/* =========================================================
   DESCRIPTION CONTAINER
   ========================================================= */

.related-bottom {
    grid-column: 2 !important;
    grid-row: 2 !important;

    width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    align-self: center !important;

    box-sizing: border-box !important;
}


/* =========================================================
   DESCRIPTION
   ========================================================= */

.related-description {
    width: 100% !important;

    max-width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    color: #31526b !important;

    font-size: 13px !important;

    line-height: 1.5 !important;

    font-weight: 400 !important;

    text-align: left !important;
}


/* =========================================================
   REMOVE BUILDER DEFAULT SPACING
   ========================================================= */

.related-product,
.related-product > div,
.related-product > section,
.related-product p,
.related-product h1,
.related-product h2,
.related-product h3,
.related-product h4,
.related-product h5,
.related-product h6 {
    box-sizing: border-box !important;

    margin-top: 0 !important;
}


/* =========================================================
   CATEGORY HOVER
   ========================================================= */

.related-product:hover .related-eyebrow-text {
    color: #f28c28 !important;
}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 900px) {

    #related-products {
        width: 94% !important;

        max-width: 94% !important;

        padding: 24px !important;

        grid-template-columns: repeat(2, minmax(0, 1fr)) !important;

        gap: 18px !important;
    }


    .related-product {
        padding: 20px !important;

        column-gap: 16px !important;
    }


    .related-title {
        font-size: 25px !important;
    }


    .related-image {
        height: 175px !important;
    }
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 650px) {

    #related-products {
        width: 94% !important;

        max-width: 94% !important;

        padding: 18px !important;

        grid-template-columns: 1fr !important;

        gap: 18px !important;
    }


    .related-product {
        width: 100% !important;

        padding: 20px !important;

        grid-template-columns: 1fr 1fr !important;
    }


    .related-title {
        font-size: 25px !important;
    }


    .related-image {
        height: 180px !important;
    }


    .related-description {
        font-size: 13px !important;
    }
}


/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width: 420px) {

    #related-products {
        padding: 14px !important;
    }


    .related-product {
        padding: 16px !important;

        column-gap: 12px !important;
    }


    .related-title {
        font-size: 22px !important;
    }


    .related-image {
        height: 155px !important;
    }
}

/* =========================================================
   MARSOL CAREERS PAGE
   CLEAN REFERENCE LAYOUT
   ========================================================= */


/* =========================================================
   GLOBAL
   ========================================================= */

html,
body {
    margin: 0 !important;
    padding: 0 !important;

    background: #FAFAF7 !important;
    color: #14140F !important;

    font-family: Inter, Arial, sans-serif !important;
}

* {
    box-sizing: border-box !important;
}


/* =========================================================
   CAREERS HERO
   ========================================================= */

.careers-hero {
    width: 100% !important;
    max-width: 100% !important;

    margin: 0 !important;

    /*
       Reduced bottom space so the jobs
       section follows naturally.
    */
    padding: 78px 32px 48px !important;

    background: #FAFAF7 !important;

    height: auto !important;
    min-height: 0 !important;

    box-sizing: border-box !important;

    overflow: visible !important;
}


/* =========================================================
   HERO CONTAINER
   ========================================================= */

.careers-hero-container {
    width: 100% !important;

    max-width: 1220px !important;

    margin-left: auto !important;
    margin-right: auto !important;

    padding: 0 !important;

    height: auto !important;
    min-height: 0 !important;

    box-sizing: border-box !important;
}


/* =========================================================
   HERO STACK
   ========================================================= */

.careers-hero-stack {
    width: 100% !important;

    max-width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    height: auto !important;
    min-height: 0 !important;

    display: flex !important;

    flex-direction: column !important;

    align-items: flex-start !important;
    justify-content: flex-start !important;

    /*
       IMPORTANT:
       Prevent Builder from creating
       a large vertical gap.
    */
    gap: 0 !important;

    box-sizing: border-box !important;
}


/* =========================================================
   EYEBROW
   ========================================================= */

.careers-eyebrow {
    display: flex !important;

    align-items: center !important;

    gap: 9px !important;

    width: auto !important;

    height: auto !important;
    min-height: 0 !important;

    margin: 0 0 24px 0 !important;
    padding: 0 !important;

    font-size: 11px !important;

    font-weight: 600 !important;

    line-height: 1.3 !important;

    letter-spacing: 0.14em !important;

    text-transform: uppercase !important;

    color: #164F91 !important;

    box-sizing: border-box !important;
}


/* =========================================================
   EYEBROW DOTS
   ========================================================= */

.careers-eyebrow::before {
    content: "" !important;

    width: 7px !important;
    height: 7px !important;

    min-width: 7px !important;
    min-height: 7px !important;

    flex-shrink: 0 !important;

    border-radius: 50% !important;

    background: #F97316 !important;

    box-shadow: 15px 0 0 #7E9B1C !important;

    margin-right: 15px !important;
}


/* =========================================================
   CAREERS TITLE
   ========================================================= */

.careers-title {
    width: 100% !important;

    max-width: 900px !important;

    height: auto !important;
    min-height: 0 !important;

    margin: 0 !important;
    padding: 0 !important;

    font-family: "Space Grotesk", Inter, Arial, sans-serif !important;

    font-size: clamp(52px, 6vw, 78px) !important;

    font-weight: 500 !important;

    line-height: 1.02 !important;

    letter-spacing: -0.045em !important;

    color: #14140F !important;

    box-sizing: border-box !important;
}


/* =========================================================
   HERO SUBTITLE
   ========================================================= */

.careers-subtitle {
    width: 100% !important;

    max-width: 700px !important;

    height: auto !important;
    min-height: 0 !important;

    margin: 24px 0 0 0 !important;
    padding: 0 !important;

    font-family: Inter, Arial, sans-serif !important;

    font-size: 17px !important;

    font-weight: 400 !important;

    line-height: 1.6 !important;

    letter-spacing: 0 !important;

    color: #66747D !important;

    box-sizing: border-box !important;
}


/* =========================================================
   FORCE INNER BUILDER TEXT
   ========================================================= */

.careers-eyebrow *,
.careers-eyebrow p,
.careers-eyebrow span,
.careers-eyebrow div {

    margin: 0 !important;
    padding: 0 !important;

    font-size: 11px !important;

    line-height: 1.3 !important;

    font-weight: 600 !important;

    letter-spacing: 0.14em !important;

    text-transform: uppercase !important;

    color: #164F91 !important;
}


.careers-title *,
.careers-title p,
.careers-title span,
.careers-title div,
.careers-title h1,
.careers-title h2,
.careers-title h3 {

    margin: 0 !important;
    padding: 0 !important;

    font-family: "Space Grotesk", Inter, Arial, sans-serif !important;

    font-size: inherit !important;

    line-height: 1.02 !important;

    font-weight: 500 !important;

    letter-spacing: -0.045em !important;

    color: #14140F !important;
}


.careers-subtitle *,
.careers-subtitle p,
.careers-subtitle span,
.careers-subtitle div {

    margin: 0 !important;
    padding: 0 !important;

    font-family: Inter, Arial, sans-serif !important;

    font-size: 17px !important;

    line-height: 1.6 !important;

    font-weight: 400 !important;

    color: #66747D !important;
}


/* =========================================================
   JOBS SECTION
   ========================================================= */

.jobs-section {
    width: 100% !important;
    max-width: 100% !important;

    margin: 0 !important;

    /*
       Small top spacing only.
       No huge gap.
    */
    padding: 24px 32px 90px !important;

    background: #FAFAF7 !important;

    height: auto !important;
    min-height: 0 !important;

    box-sizing: border-box !important;
}


/* =========================================================
   JOBS CONTAINER
   ========================================================= */

.jobs-container {
    width: 100% !important;

    max-width: 1220px !important;

    margin-left: auto !important;
    margin-right: auto !important;

    padding: 0 !important;

    height: auto !important;
    min-height: 0 !important;

    box-sizing: border-box !important;
}


/* =========================================================
   HIDE "OPEN POSITIONS"

   Reference design goes directly from hero
   into the job list.

   IMPORTANT:
   This only hides the heading.
   It does NOT affect the DocType/repeater.
   ========================================================= */

.jobs-title {
    display: none !important;

    height: 0 !important;
    min-height: 0 !important;

    margin: 0 !important;
    padding: 0 !important;

    border: none !important;
}


/* =========================================================
   JOB REPEATER
   ========================================================= */

.job-repeater {
    width: 100% !important;

    max-width: 1220px !important;

    height: auto !important;
    min-height: 0 !important;

    margin: 0 auto !important;
    padding: 0 !important;

    display: flex !important;

    flex-direction: column !important;

    align-items: stretch !important;

    gap: 0 !important;

    background: transparent !important;

    box-sizing: border-box !important;
}


/* =========================================================
   JOB CARD
   ========================================================= */

.job-repeater .job-card,
.job-card {
    position: relative !important;

    width: 100% !important;
    max-width: 100% !important;

    height: auto !important;
    min-height: 0 !important;

    margin: 0 !important;

    /*
       Reference-style job row.
    */
    padding: 30px 0 !important;

    display: flex !important;

    flex-direction: column !important;

    justify-content: center !important;

    align-items: flex-start !important;

    background: transparent !important;

    border: none !important;

    border-top: 1px solid #D9DEDF !important;

    border-bottom: none !important;

    border-radius: 0 !important;

    box-shadow: none !important;

    overflow: visible !important;

    box-sizing: border-box !important;

    /*
       Keep existing hover functionality.
    */
    transition:
        background-color 0.25s ease,
        padding-left 0.25s ease !important;
}


/* =========================================================
   LAST JOB CARD
   ========================================================= */

.job-repeater .job-card:last-child {
    border-bottom: 1px solid #D9DEDF !important;
}


