/* =========================================================
   DIFF SYSTEM — COMPACT PRODUCT HERO
   =========================================================

   Builder structure:

   Section · Hero
   └── Hero Container       = product-hero
       └── Hero Stack        = product-hero-stack
           ├── Eyebrow
           │   └── Hero Subtitle = related-description
           │
           ├── Hero Title        = product-title
           │
           ├── img               = product-image
           │
           └── Hero Bottom Row
               └── Hero Subtitle = product-description

   Section Hero itself has NO class.
   ========================================================= */


/* =========================================================
   1. HERO CONTAINER
   ========================================================= */

.product-hero {
    width: 100% !important;
    max-width: 100% !important;

    margin: 0 !important;

    /* LESS EMPTY SPACE */
    padding: 45px 6% 50px 6% !important;

    background: #ffffff !important;

    box-sizing: border-box !important;

    overflow: hidden !important;

    min-height: 0 !important;
    height: auto !important;
}


/* =========================================================
   2. HERO STACK
   ========================================================= */

.product-hero-stack {
    width: 100% !important;

    max-width: 1250px !important;

    margin: 0 auto !important;
    padding: 0 !important;

    display: grid !important;

    /*
       LEFT CONTENT + SMALLER IMAGE
    */
    grid-template-columns: minmax(0, 1fr) 400px !important;

    /*
       IMPORTANT:
       Keep rows compact instead of allowing
       the image to create huge empty spaces.
    */
    grid-template-rows: auto auto auto !important;

    column-gap: 70px !important;
    row-gap: 0 !important;

    align-items: center !important;

    box-sizing: border-box !important;

    min-height: 0 !important;
    height: auto !important;
}


/* =========================================================
   3. GLOBAL RESET
   ========================================================= */

.product-hero,
.product-hero * {
    box-sizing: border-box !important;
}


.product-hero h1,
.product-hero h2,
.product-hero h3,
.product-hero h4,
.product-hero h5,
.product-hero h6,
.product-hero p {
    margin-top: 0 !important;
}


