// Fetch stock through Marsol Product → ERPNext Item
document.addEventListener("DOMContentLoaded", async function () {
    try {
        // Get all "Stock Available" text elements
        const stockElements = [...document.querySelectorAll("body *")].filter(
            el =>
                el.children.length === 0 &&
                el.textContent.trim() === "Stock Available"
        );

        // Marsol Product IDs in the SAME ORDER as the cards
        const productIds = [
            "dqqf5hkfi3",
            "rnsrtjutdp",
            "srru839ge8"
        ];

        // Fetch stock for each Marsol Product
        const stockResults = await Promise.all(
            productIds.map(async (productId) => {
                const response = await fetch(
                    `/api/method/marsol_website.api.stock.get_stock?product_id=${encodeURIComponent(productId)}`
                );

                const result = await response.json();

                return {
                    product: result.message?.product || "",
                    itemCode: result.message?.item_code || "",
                    stockQty: result.message?.stock_qty ?? 0
                };
            })
        );

        // Update each card's stock text
        stockResults.forEach((product, index) => {
            const stockElement = stockElements[index];

            if (stockElement) {
                stockElement.textContent = `Stock: ${product.stockQty}`;
            }
        });

    } catch (error) {
        console.error("Failed to fetch product stock:", error);
    }
});

