/* =========================================================
   PRODUCT CARD
   ========================================================= */

.product-card {
    position: relative !important;

    width: 100% !important;

    height: 280px !important;
    min-height: 280px !important;
    max-height: 280px !important;

    background: #ffffff !important;

    border: 1px solid #d5dad7 !important;
    border-radius: 4px !important;

    margin: 0 !important;
    padding: 30px !important;

    overflow: hidden !important;

    display: block !important;

    box-sizing: border-box !important;

    cursor: pointer !important;

    transition:
        transform 0.25s ease,
        border-color 0.25s ease,
        box-shadow 0.25s ease !important;
}


/* =========================================================
   HOVER
   ========================================================= */

.product-card:hover {
    transform: translateY(-5px) !important;

    border-color: #ff7518 !important;

    box-shadow:
        0 12px 30px rgba(0,0,0,0.08) !important;
}


/* =========================================================
   PRODUCT IMAGE
   ========================================================= */

.product-card img,
.product-card picture,
.product-card video {

    position: absolute !important;

    top: 25px !important;
    right: 25px !important;

    width: 45% !important;
    max-width: 190px !important;

    height: 170px !important;
    max-height: 170px !important;

    object-fit: contain !important;
    object-position: center !important;

    margin: 0 !important;
    padding: 0 !important;

    z-index: 1 !important;

    box-sizing: border-box !important;
}


/* =========================================================
   PRODUCT IMAGE CLASS
   ========================================================= */

.product-image {
    position: absolute !important;

    top: 25px !important;
    right: 25px !important;

    width: 45% !important;
    max-width: 190px !important;

    height: 170px !important;
    max-height: 170px !important;

    object-fit: contain !important;
    object-position: center !important;

    margin: 0 !important;
    padding: 0 !important;

    z-index: 1 !important;
}


/* =========================================================
   PICTURE WRAPPER
   ========================================================= */

.product-card picture img {
    position: static !important;

    width: 100% !important;
    max-width: 100% !important;

    height: 100% !important;
    max-height: 100% !important;

    object-fit: contain !important;
}


/* =========================================================
   META
   ========================================================= */

.product-meta {
    position: relative !important;

    width: 100% !important;
    height: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    z-index: 3 !important;

    box-sizing: border-box !important;
}


/* =========================================================
   TEXT AREA
   ========================================================= */

.product-copy {
    position: relative !important;

    width: 48% !important;
    max-width: 300px !important;

    margin: 0 !important;
    padding: 0 !important;

    z-index: 4 !important;
}


/* =========================================================
   TITLE
   ========================================================= */

.product-title {
    color: #071b2b !important;

    font-size: 24px !important;
    line-height: 1.15 !important;

    font-weight: 700 !important;

    margin: 0 0 12px 0 !important;
    padding: 0 !important;

    letter-spacing: -0.3px !important;
}


/* =========================================================
   DESCRIPTION
   ========================================================= */

.product-description {
    color: #405466 !important;

    font-size: 14px !important;
    line-height: 1.5 !important;

    font-weight: 400 !important;

    margin: 0 !important;
    padding: 0 !important;

    max-width: 250px !important;
}


/* =========================================================
   YEAR / BRAND
   ========================================================= */

.product-year {
    position: absolute !important;

    right: 5px !important;
    bottom: 2px !important;

    color: #68747b !important;

    font-size: 9px !important;

    letter-spacing: 1.5px !important;

    text-transform: uppercase !important;

    margin: 0 !important;
    padding: 0 !important;

    z-index: 5 !important;
}


/* =========================================================
   ORANGE BOTTOM LINE
   ========================================================= */

.product-card::before {
    content: "" !important;

    position: absolute !important;

    left: 0 !important;
    bottom: 0 !important;

    width: 0 !important;
    height: 4px !important;

    background: #ff7518 !important;

    transition: width 0.3s ease !important;

    z-index: 10 !important;
}

.product-card:hover::before {
    width: 100% !important;
}


/* =========================================================
   ARROW
   ========================================================= */

.product-card::after {
    content: "→" !important;

    position: absolute !important;

    right: 25px !important;
    bottom: 20px !important;

    color: #ff7518 !important;

    font-size: 22px !important;

    opacity: 0 !important;

    transform: translateX(-8px) !important;

    transition:
        opacity 0.25s ease,
        transform 0.25s ease !important;

    z-index: 10 !important;
}

.product-card:hover::after {
    opacity: 1 !important;

    transform: translateX(0) !important;
}


/* =========================================================
   REMOVE RANDOM MARGINS
   ========================================================= */

.product-card h1,
.product-card h2,
.product-card h3,
.product-card h4,
.product-card h5,
.product-card h6,
.product-card p {
    margin-top: 0 !important;
}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 900px) {

    .work-section {
        padding: 70px 0 85px !important;
    }

    .work-container {
        width: 90% !important;
    }

    .work-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
        grid-auto-rows: 250px !important;
        gap: 16px !important;
    }

    .product-card {
        height: 250px !important;
        min-height: 250px !important;
        max-height: 250px !important;

        padding: 25px !important;
    }

    .product-card img,
    .product-image {
        width: 44% !important;
        max-width: 145px !important;

        height: 145px !important;
        max-height: 145px !important;
    }

    .product-title {
        font-size: 21px !important;
    }
}


