// ============================================================
// MARSoL GLOBAL SEARCH
// ============================================================

(function () {

    console.log("MARSoL Search: loaded");

    // ----------------------------------------------------------
    // WEBSITE PAGES
    // ----------------------------------------------------------

    const pages = [
        {
            title: "Home",
            url: "/pages/homepage",
            content: "Marsol Technologies fire suppression systems engineered products marine offshore aviation industrial"
        },
        {
            title: "Products",
            url: "/pages/product",
            content: "Marsol products fire suppression systems DIFF System DIFF Nozzles Self-Contained Skid Foam Proportioner Roto-Spray PFAS Advanced Oxidation Hose Reel Foam Bladder Tank"
        },
        {
            title: "Environmental",
            url: "/pages/enviornment",
            content: "Environmental solutions sustainability water treatment PFAS extraction advanced oxidation"
        },
        {
            title: "About",
            url: "/pages/Abouts",
            content: "About Marsol Technologies company fire protection engineering marine offshore aviation industrial"
        },
        {
            title: "News",
            url: "/pages/news",
            content: "Marsol news latest news updates announcements"
        },
        {
            title: "Careers",
            url: "/pages/career",
            content: "Careers jobs opportunities employment work with Marsol"
        },
        {
            title: "Contacts",
            url: "/pages/Contact",
            content: "Contact Marsol Technologies get in touch email phone address"
        }
    ];


    // ----------------------------------------------------------
    // HELPERS
    // ----------------------------------------------------------

    function normalize(value) {
        return String(value || "")
            .toLowerCase()
            .replace(/\s+/g, " ")
            .trim();
    }


    function slugify(value) {
        return String(value || "")
            .toLowerCase()
            .trim()
            .replace(/&/g, "and")
            .replace(/[^a-z0-9]+/g, "-")
            .replace(/^-+|-+$/g, "");
    }


    function escapeHTML(value) {
        return String(value || "")
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");
    }


    // ==========================================================
    // CREATE SEARCH BOX
    // ==========================================================

    function createSearchBox() {

        if (document.getElementById("marsol-search-box")) {
            return;
        }

        const box = document.createElement("div");

        box.id = "marsol-search-box";

        box.innerHTML = `
            <div class="marsol-search-panel">

                <div class="marsol-search-header">

                    <span class="marsol-search-title">
                        Search Marsol
                    </span>

                    <button
                        type="button"
                        id="marsol-search-close"
                    >
                        ×
                    </button>

                </div>

                <div class="marsol-search-input-row">

                    <input
                        type="text"
                        id="marsol-search-input"
                        placeholder="Search Marsol..."
                        autocomplete="off"
                    >

                    <button
                        type="button"
                        id="marsol-search-submit"
                    >
                        Search
                    </button>

                </div>

                <div id="marsol-search-results"></div>

            </div>
        `;

        document.body.appendChild(box);


        // ------------------------------------------------------
        // CSS
        // ------------------------------------------------------

        const style = document.createElement("style");

        style.id = "marsol-search-style";

        style.textContent = `

            #marsol-search-box {
                position: fixed;
                display: none;
                z-index: 999999999;
                width: 330px;
                box-sizing: border-box;
                font-family: Arial, sans-serif;
            }

            .marsol-search-panel {
                width: 330px;
                max-width: calc(100vw - 20px);
                background: #ffffff;
                border: 1px solid #e5e5e5;
                border-radius: 10px;
                padding: 14px;
                box-sizing: border-box;
                box-shadow: 0 8px 25px rgba(0,0,0,0.18);
            }

            .marsol-search-header {
                display: flex;
                align-items: center;
                justify-content: space-between;
                margin-bottom: 10px;
            }

            .marsol-search-title {
                font-size: 17px;
                font-weight: 700;
                color: #222;
            }

            #marsol-search-close {
                border: none;
                background: transparent;
                color: #555;
                font-size: 24px;
                line-height: 1;
                cursor: pointer;
                padding: 0;
            }

            .marsol-search-input-row {
                display: flex;
                gap: 7px;
                width: 100%;
            }

            #marsol-search-input {
                flex: 1;
                min-width: 0;
                height: 40px;
                padding: 8px 10px;
                border: 1px solid #cccccc;
                border-radius: 7px;
                font-size: 14px;
                box-sizing: border-box;
                outline: none;
            }

            #marsol-search-input:focus {
                border-color: #777;
            }

            #marsol-search-submit {
                height: 40px;
                padding: 0 14px;
                border: none;
                border-radius: 7px;
                background: #ff6b00;
                color: white;
                font-size: 14px;
                font-weight: 600;
                cursor: pointer;
                white-space: nowrap;
            }

            #marsol-search-submit:hover {
                background: #e85f00;
            }

            #marsol-search-results {
                margin-top: 10px;
                max-height: 250px;
                overflow-y: auto;
            }

            .marsol-result {
                padding: 10px;
                margin-bottom: 6px;
                border: 1px solid #e5e5e5;
                border-radius: 7px;
                cursor: pointer;
                background: #fff;
            }

            .marsol-result:hover {
                background: #f5f5f5;
            }

            .marsol-result-title {
                font-size: 14px;
                font-weight: 700;
                margin-bottom: 3px;
            }

            .marsol-result-description {
                font-size: 12px;
                color: #666;
                line-height: 1.4;
            }

            .marsol-result-type {
                margin-top: 5px;
                font-size: 10px;
                font-weight: 600;
                color: #777;
                text-transform: uppercase;
            }

            .marsol-no-result {
                padding: 12px 5px;
                text-align: center;
                font-size: 13px;
                color: #777;
            }

            @media (max-width: 600px) {

                #marsol-search-box {
                    width: calc(100vw - 20px);
                }

                .marsol-search-panel {
                    width: 100%;
                }

            }

        `;

        document.head.appendChild(style);
    }


    // ==========================================================
    // POSITION BELOW SEARCH BUTTON
    // ==========================================================

    function positionSearch(button) {

        const box =
            document.getElementById("marsol-search-box");

        if (!box || !button) {
            return;
        }

        const rect =
            button.getBoundingClientRect();

        const boxWidth = 330;

        const gap = 6;

        let left =
            rect.right - boxWidth;

        let top =
            rect.bottom + gap;


        // Keep inside screen

        if (left < 10) {
            left = 10;
        }

        if (left + boxWidth > window.innerWidth - 10) {
            left = window.innerWidth - boxWidth - 10;
        }


        box.style.left = left + "px";
        box.style.top = top + "px";
    }


    // ==========================================================
    // OPEN SEARCH
    // ==========================================================

    function openSearch(button) {

        createSearchBox();

        const box =
            document.getElementById("marsol-search-box");

        const input =
            document.getElementById("marsol-search-input");

        box.style.display = "block";

        positionSearch(button);

        setTimeout(function () {
            input.focus();
        }, 50);
    }


    // ==========================================================
    // CLOSE SEARCH
    // ==========================================================

    function closeSearch() {

    const box =
        document.getElementById("marsol-search-box");

    const input =
        document.getElementById("marsol-search-input");

    const results =
        document.getElementById("marsol-search-results");


    if (input) {
        input.value = "";
    }


    if (results) {
        results.innerHTML = "";
    }


    if (box) {
        box.style.display = "none";
    }

}


    // ==========================================================
    // GET PRODUCTS
    // ==========================================================

    async function getProducts() {

        try {

            const response = await fetch(
                "/api/method/marsol_website.api.products.get_products",
                {
                    cache: "no-store"
                }
            );

            if (!response.ok) {
                return [];
            }

            const data =
                await response.json();

            if (Array.isArray(data.message)) {
                return data.message;
            }

            return [];

        } catch (error) {

            console.error(
                "Marsol product search error:",
                error
            );

            return [];
        }
    }


    // ==========================================================
    // SEARCH
    // ==========================================================

    async function performSearch() {

        const input =
            document.getElementById(
                "marsol-search-input"
            );

        const results =
            document.getElementById(
                "marsol-search-results"
            );

        if (!input || !results) {
            return;
        }

        const query =
            normalize(input.value);

        results.innerHTML = "";


        if (!query) {

            results.innerHTML = `
                <div class="marsol-no-result">
                    Type something to search.
                </div>
            `;

            return;
        }


        results.innerHTML = `
            <div class="marsol-no-result">
                Searching...
            </div>
        `;


        // ------------------------------------------------------
        // PAGES
        // ------------------------------------------------------

        const pageResults =
            pages.filter(function(page) {

                const text =
                    normalize(
                        page.title +
                        " " +
                        page.content
                    );

                return text.includes(query);
            });


        // ------------------------------------------------------
        // PRODUCTS
        // ------------------------------------------------------

        const products =
            await getProducts();

        const productResults =
            products.filter(function(product) {

                const text =
                    normalize(
                        (product.product_name || "") +
                        " " +
                        (product.description || "") +
                        " " +
                        (product.category || "")
                    );

                return text.includes(query);
            });


        results.innerHTML = "";


        // ------------------------------------------------------
        // NO RESULTS
        // ------------------------------------------------------

        if (
            pageResults.length === 0 &&
            productResults.length === 0
        ) {

            results.innerHTML = `
                <div class="marsol-no-result">
                    No results found for
                    "<strong>${escapeHTML(query)}</strong>"
                </div>
            `;

            return;
        }


        // ------------------------------------------------------
        // PAGE RESULTS
        // ------------------------------------------------------

        pageResults.forEach(function(page) {

            const item =
                document.createElement("div");

            item.className =
                "marsol-result";

            item.innerHTML = `

                <div class="marsol-result-title">
                    ${escapeHTML(page.title)}
                </div>

                <div class="marsol-result-description">
                    ${escapeHTML(page.content)}
                </div>

                <div class="marsol-result-type">
                    Page
                </div>

            `;

            item.addEventListener(
                "click",
                function() {

                    window.location.href =
                        page.url;

                }
            );

            results.appendChild(item);
        });


        // ------------------------------------------------------
        // PRODUCT RESULTS
        // ------------------------------------------------------

        productResults.forEach(function(product) {

            const name =
                product.product_name ||
                "Product";

            const description =
                product.description ||
                "Marsol product";

            const category =
                product.category ||
                "";

            const url =
                "/products/" +
                slugify(name);


            const item =
                document.createElement("div");

            item.className =
                "marsol-result";

            item.innerHTML = `

                <div class="marsol-result-title">
                    ${escapeHTML(name)}
                </div>

                <div class="marsol-result-description">
                    ${escapeHTML(description)}
                </div>

                <div class="marsol-result-type">
                    Product
                    ${
                        category
                            ? " • " +
                              escapeHTML(category)
                            : ""
                    }
                </div>

            `;

            item.addEventListener(
                "click",
                function() {

                    window.location.href =
                        url;

                }
            );

            results.appendChild(item);
        });

    }


    // ==========================================================
    // IMPORTANT:
    // CAPTURE CLICK ON SEARCH BUTTON
    // ==========================================================
    //
    // The "true" here is VERY IMPORTANT.
    //
    // It catches the Search button click BEFORE
    // Frappe Builder's existing Contact navigation.
    //
    // ==========================================================

    document.addEventListener(
        "click",
        function(event) {

            const button =
                event.target.closest(
                    ".marsol-search-button"
                );

            if (!button) {
                return;
            }


            // STOP OLD CONTACT LINK

            event.preventDefault();

            event.stopPropagation();

            event.stopImmediatePropagation();


            console.log(
                "Marsol Search button clicked"
            );


            openSearch(button);

        },
        true
    );


    // ==========================================================
    // SEARCH SUBMIT
    // ==========================================================

    document.addEventListener(
        "click",
        function(event) {

            const submit =
                event.target.closest(
                    "#marsol-search-submit"
                );

            if (!submit) {
                return;
            }

            event.preventDefault();

            event.stopPropagation();

            performSearch();

        }
    );


    // ==========================================================
    // CLOSE
    // ==========================================================

    document.addEventListener(
        "click",
        function(event) {

            const close =
                event.target.closest(
                    "#marsol-search-close"
                );

            if (!close) {
                return;
            }

            event.preventDefault();

            closeSearch();

        }
    );


    // ==========================================================
    // ENTER + ESC
    // ==========================================================

    document.addEventListener(
        "keydown",
        function(event) {

            if (
                event.key === "Enter" &&
                event.target &&
                event.target.id ===
                    "marsol-search-input"
            ) {

                event.preventDefault();

                performSearch();
            }


            if (event.key === "Escape") {

                closeSearch();

            }

        }
    );


    // ==========================================================
    // CLOSE WHEN CLICKING OUTSIDE
    // ==========================================================

    document.addEventListener(
        "click",
        function(event) {

            const box =
                document.getElementById(
                    "marsol-search-box"
                );

            if (!box) {
                return;
            }

            if (
                box.style.display !==
                "block"
            ) {
                return;
            }

            const panel =
                event.target.closest(
                    ".marsol-search-panel"
                );

            const button =
                event.target.closest(
                    ".marsol-search-button"
                );

            if (
                !panel &&
                !button
            ) {

                closeSearch();

            }

        }
    );


    // ==========================================================
    // KEEP POSITION ON RESIZE
    // ==========================================================

    window.addEventListener(
        "resize",
        function() {

            const box =
                document.getElementById(
                    "marsol-search-box"
                );

            if (
                !box ||
                box.style.display !== "block"
            ) {
                return;
            }

            const button =
                document.querySelector(
                    ".marsol-search-button"
                );

            if (button) {

                positionSearch(button);

            }

        }
    );


    console.log(
